        "label": "Fetch Expense Details"
      },
      "inputs": {
        "script": "return {\n  expenseId: \"EXP-2024-0042\",\n  amount: 1250.00,\n  submitter: \"Jane Smith\",\n  category: \"Travel\"\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The expense details returned by the script",
          "source": "=result.response",
          "var": "output"
        },
